    ::roo_transceivers::ServerMessage_DeviceModified device_modified_;
    ::roo_transceivers::ServerMessage_UpdateEnd transceiver_update_end_;
    ::roo_transceivers::ServerMessage_ReadingsBegin readings_begin_;
    ::roo_transceivers::ServerMessage_Reading reading_;
    ::roo_transceivers::ServerMessage_ReadingsEnd readings_end_;
